REPO_LEGACY_DIR = ".control"
WORKSPACE_ENV = ("BROOMVA_WORKSPACE", "MAESTRO_WORKSPACE", "BSTACK_WORKSPACE")
WORKSPACE_DEFAULT = "~/broomva"
MACHINE_ENV = "BROOMVA_HOME"
MACHINE_DEFAULT = "~/.broomva"

